import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"缓存策略与一致性","description":"先明确缓存解决的读压力或延迟问题，再选择失效、更新与降级策略，避免缓存成为第二份失控的数据源。","frontmatter":{"title":"缓存策略与一致性","description":"先明确缓存解决的读压力或延迟问题，再选择失效、更新与降级策略，避免缓存成为第二份失控的数据源。"},"headers":[],"relativePath":"backend/cache.md","filePath":"backend/cache.md","lastUpdated":1786265286000}'),d={name:"backend/cache.md"};function i(o,t,r,l,p,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="缓存策略与一致性" tabindex="-1">缓存策略与一致性 <a class="header-anchor" href="#缓存策略与一致性" aria-label="Permalink to &quot;缓存策略与一致性&quot;">​</a></h1><p>缓存以更低成本换取更快读取，但也引入“数据何时更新”的问题。没有读瓶颈或明确收益时，不要先加缓存；先让查询、索引和接口边界正确。</p><h2 id="明确缓存的对象和目标" tabindex="-1">明确缓存的对象和目标 <a class="header-anchor" href="#明确缓存的对象和目标" aria-label="Permalink to &quot;明确缓存的对象和目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缓存对象</th><th>常见目标</th><th>需要格外注意</th></tr></thead><tbody><tr><td>配置、字典数据</td><td>降低重复读取</td><td>更新频率与版本</td></tr><tr><td>热门详情、列表</td><td>降低数据库读压力</td><td>分页、权限、失效范围</td></tr><tr><td>会话、临时令牌</td><td>快速验证身份</td><td>过期与撤销</td></tr><tr><td>计算结果</td><td>避免重复计算</td><td>输入变化与结果有效期</td></tr></tbody></table><p>缓存键应包含真正影响结果的维度，例如语言、租户、权限版本和筛选条件。缺少维度会造成数据串读；维度过多则命中率很低。</p><h2 id="缓存旁路是常见起点" tabindex="-1">缓存旁路是常见起点 <a class="header-anchor" href="#缓存旁路是常见起点" aria-label="Permalink to &quot;缓存旁路是常见起点&quot;">​</a></h2><p>读取时先查缓存，未命中再查主数据源并回填；更新时先写主数据源，再删除或更新缓存。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读取：cache → miss → database → cache</span></span>
<span class="line"><span>更新：database → invalidate cache</span></span></code></pre></div><p>“删除缓存”通常比直接更新更简单，因为复杂对象的局部更新容易遗漏字段。但删除与下次读取之间仍可能发生并发竞态，需要根据重要性评估是否接受短暂旧值。</p><h2 id="为异常情况提前设计" tabindex="-1">为异常情况提前设计 <a class="header-anchor" href="#为异常情况提前设计" aria-label="Permalink to &quot;为异常情况提前设计&quot;">​</a></h2><ul><li><strong>缓存穿透</strong>：反复查询不存在的数据。可缓存短期空值，并对异常输入限流。</li><li><strong>缓存击穿</strong>：热点键刚失效时大量请求同时回源。使用互斥、请求合并或预热。</li><li><strong>缓存雪崩</strong>：大量键同一时间失效。给 TTL 加随机扰动，并准备回源保护。</li><li><strong>缓存不可用</strong>：服务必须能降级到主数据源，或明确拒绝非关键请求。</li></ul><h2 id="常见错误-缓存键缺少维度导致串读" tabindex="-1">常见错误：缓存键缺少维度导致串读 <a class="header-anchor" href="#常见错误-缓存键缺少维度导致串读" aria-label="Permalink to &quot;常见错误：缓存键缺少维度导致串读&quot;">​</a></h2><p>缓存键没把所有影响结果的维度都包含进去，是缓存最危险的问题——不会报错，只会悄悄返回错误数据：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 多租户系统，key 只用了文章 id</span></span>
<span class="line"><span>key: &quot;article:18&quot;  → 存的是 A 租户、中文版的内容</span></span></code></pre></div><p><strong>症状</strong>：B 租户的用户打开了同一篇文章，看到的却是 A 租户的内容；英文用户看到中文；普通用户看到了管理员才能看的版本。这类 bug 极难发现——因为数据&quot;看起来正常&quot;，只是张冠李戴，往往要等用户投诉&quot;看到了别人的数据&quot;才暴露。</p><p><strong>为什么错</strong>：缓存键是命中缓存的唯一依据。只要 key 相同，就返回同一份缓存，不管请求实际来自哪个租户、哪种语言、什么权限。漏掉一个维度，不同输入就会命中同一份结果。</p><p><strong>正确做法</strong>：key 必须包含所有影响结果的维度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key: &quot;article:18:tenant:B:lang:en:perm:v2&quot;</span></span>
<span class="line"><span>// 文章 id + 租户 + 语言 + 权限版本</span></span></code></pre></div><p>拿不准要不要加某个维度时，问一句：<strong>&quot;这个维度的不同值，会产生不同的结果吗？&quot;</strong> 会，就必须进 key。</p><h2 id="一致性是业务选择" tabindex="-1">一致性是业务选择 <a class="header-anchor" href="#一致性是业务选择" aria-label="Permalink to &quot;一致性是业务选择&quot;">​</a></h2><p>库存、余额、权限等强敏感数据，不能因为缓存快就接受陈旧值；推荐内容、统计数字等可根据业务容忍度使用短暂最终一致。把“允许旧多久、错了怎么办”写成规则，缓存才不会成为隐形风险。</p>`,21)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
